import {
  Color,
  WebGLRenderer,
  PCFShadowMap,
  NeutralToneMapping,
  PMREMGenerator,
  Scene,
  type Camera,
  type Fog,
  type Mesh,
  type Texture,
} from 'three';
import { pass } from 'three/tsl';
import { TimestampQuery } from 'three/webgpu';
import { QualityMode } from './utils/quality';
import {
  WebGPURenderer,
  RenderPipeline,
  HemisphereLight,
  PMREMGenerator as WebGPUPMREMGenerator,
} from 'three/webgpu';
import { bloom } from 'three/addons/tsl/display/BloomNode.js';
import { fxaa } from 'three/addons/tsl/display/FXAANode.js';
import { WebGLNodesHandler } from 'three/examples/jsm/tsl/WebGLNodesHandler.js';
import { app } from './';

type FuseRendererOptions = {
  canvas: HTMLElement | null;
  adaptive?: boolean;
  antialias?: boolean;
  width?: number;
  height?: number;
  aspect?: number;
  container?: HTMLElement;
  renderMode?: 'webgl' | 'webgpu';
  forceWebGL?: boolean,
  qualityLevel?: QualityMode;
}

export class FuseRenderer {
  renderer: WebGLRenderer | WebGPURenderer;
  container: HTMLElement;
  width: number;
  height: number;
  qualityLevel: QualityMode;
  adaptive: boolean;
  adaptiveHold = false;
  #basePixelRatio = 1;
  #minScale = 0.5;
  #scale = 1;
  #targetMs = 1000 / 30;
  #emaMs = 0;
  #lastFrameT = 0;
  #lastAdjustT = 0;
  #recoverAfter = 0;
  #adaptiveActive = false;
  environment?: Texture;
  pipeline?: RenderPipeline;
  constructor(options: FuseRendererOptions) {
    if (!options.canvas || !(options.canvas instanceof HTMLCanvasElement)) {
      throw new Error('Must provide a valid canvas element');
    }
    this.container = options.container ?? options.canvas.parentElement ?? document.body;
    this.width = Math.max(1, this.container.offsetWidth || window.innerWidth || 1280);
    this.height = Math.max(1, this.container.offsetHeight || window.innerHeight || 720);
    this.qualityLevel = options.qualityLevel ?? QualityMode.Medium;
    this.adaptive = options.adaptive ?? true;

    if (options.renderMode === 'webgpu') {
      // Med/High: MSAA lives on the pipeline pass → canvas AA off.
      // Low: no pipeline, so canvas MSAA provides AA — safe because Low water
      // never samples scene depth (useDepthFade: false), the other half of the bug.
      this.renderer = new WebGPURenderer({
        canvas: options.canvas,
        // antialias is handled via post-proc pipeline
        antialias: this.qualityLevel === QualityMode.Low,
        depth: true,
        forceWebGL: !!options.forceWebGL,
      });
      // @ts-expect-error - isWebGPUBackend exists not added to three types yet
      app.log(`isWebGPUBackend: ${this.renderer.backend?.isWebGPUBackend}`);
      
    } else {
      this.renderer = new WebGLRenderer({ canvas: options.canvas, antialias: options.antialias });
      // Enable TSL node material support for WebGLRenderer
      // (WebGPURenderer handles this natively)
      this.renderer.setNodesHandler(new WebGLNodesHandler());
    }
    this.renderer.setSize(this.width, this.height);  
    
    const pixelRatio = this._calculatePixelRatio(this.qualityLevel);
    this.renderer.setPixelRatio(pixelRatio);
    this.#basePixelRatio = pixelRatio;
    // fps targets: Low 30, Medium 50, High+ 60
    const targetFps = this.qualityLevel === QualityMode.Low ? 30 : 60;
    this.#targetMs = 1000 / targetFps;
    this.#emaMs = this.#targetMs;

    this.renderer.shadowMap.enabled = this.qualityLevel > QualityMode.Low;
    this.renderer.shadowMap.type = PCFShadowMap;

    // this.renderer.toneMapping = ACESFilmicToneMapping;
    // this.renderer.toneMapping = AgXToneMapping;
    this.renderer.toneMapping = NeutralToneMapping;
    this.renderer.toneMappingExposure = 1.2;

    window.addEventListener('resize', this._handleResize.bind(this));

    const resizeObserver = new ResizeObserver((_entries) => this._handleResize());
    resizeObserver.observe(this.container);
  
  }
  
  _handleResize() {  
    const w = this.container.offsetWidth || window.innerWidth;
    const h = this.container.offsetHeight || window.innerHeight;
    if (w > 0 && h > 0) {
      this.width = w;
      this.height = h;
      this.renderer.setSize(this.width, this.height);
    }
  }

  async init() {
    if (this.renderer instanceof WebGPURenderer) {
      try {
        await this.renderer.init();
      } catch (err) {
        console.warn('[FuseRenderer] WebGPU init failed, retrying with WebGL backend fallback:', err);
        const canvas = this.renderer.domElement;
        this.renderer = new WebGPURenderer({
          canvas,
          antialias: true,
          depth: true,
          forceWebGL: true,
        });
        this.renderer.setSize(this.width, this.height);
        this.renderer.setPixelRatio(this.#basePixelRatio);
        this.renderer.shadowMap.enabled = this.qualityLevel > QualityMode.Low;
        this.renderer.shadowMap.type = PCFShadowMap;
        this.renderer.toneMapping = NeutralToneMapping;
        this.renderer.toneMappingExposure = 1.2;
        await this.renderer.init();
      }
    }
  }

  async compile(scene: Scene, camera: Camera) {
    // WebGLRenderer compiles cheaply on demand only need for WebGPURenderer
    if (!(this.renderer instanceof WebGPURenderer)) return;
    try {
      if (this.pipeline) {
        // Real frames go through the pipeline — warm that path,
        // with culling disabled so every material compiles.
        const culled: any[] = [];
        scene.traverse((o: any) => {
          if (o.frustumCulled) {
            o.frustumCulled = false;
            culled.push(o);
          }
        });
        this.pipeline.render();
        for (const o of culled) o.frustumCulled = true;
      } else {
        // No post-processing
        await this.renderer.compileAsync(scene, camera);
      }
    } catch (err) {
      console.warn('[FuseRenderer] Pipeline compile warning (falling back to direct render):', err);
      this.pipeline = undefined;
    }

  }

  clear() {
    // this.renderer.clear();
  }
  
  render(scene: Scene, camera: Camera, fog?: Fog) {
    if (fog) {
      scene.fog = fog;
    }
    if (this.adaptive) {
      this.#adjustResolution(); 
    }
    if (this.pipeline) {
      try {
        this.pipeline.render();
      } catch (err) {
        console.warn('[FuseRenderer] Post-processing render error, falling back to direct render:', err);
        this.pipeline = undefined;
        this.renderer.render(scene, camera);
      }
    } else {
      this.renderer.render(scene, camera);
    }

  }

  getMaxAnisotropy() {
    if (this.renderer instanceof WebGPURenderer) {
      return this.renderer.getMaxAnisotropy();
    } else if (this.renderer instanceof WebGLRenderer) {
      return this.renderer.capabilities.getMaxAnisotropy();
    }
    return 1;
  }

  getMaxTextureSize(): number {
    const backend: any = (this.renderer as any).backend;
    // WebGPU backend
    const gpuLimit = backend?.device?.limits?.maxTextureDimension2D;
    if (gpuLimit) return gpuLimit;
    // WebGL backend
    const gl = backend?.gl;
    if (gl) return gl.getParameter(gl.MAX_TEXTURE_SIZE);
    return 4096; // conservative fallback
  }

  generateEnvironment(scene: Scene, sky?: Mesh) {
    if (!this.renderer) {
      throw new Error('Missing renderer');
    }

    const tempScene = new Scene();
    tempScene.background = scene.background || new Color('#c8dbe5');
    if (sky) {
      tempScene.add(sky);
    }
    
    const hemiLight = new HemisphereLight('#c8dbe8', '#4a7a5c', 1.0);
    tempScene.add(hemiLight);

    const pmrem = this.renderer instanceof WebGPURenderer ? new WebGPUPMREMGenerator(this.renderer) : new PMREMGenerator(this.renderer);
    this.environment = pmrem.fromScene(tempScene, 0, 0.1, 10000).texture;
    pmrem.dispose();
    
    // Move sky back to the real scene
    if (sky) scene.add(sky);
    // scene.environment = this.environment;

  }

  _calculatePixelRatio(quality: QualityMode): number {
    const dpr = typeof window !== 'undefined' ? (window.devicePixelRatio || 1) : 1;
    if (quality === QualityMode.Low) return Math.min(dpr, 1.0);
    if (quality === QualityMode.Medium) return Math.min(dpr, 1.3);
    if (quality === QualityMode.High) return Math.min(dpr, 1.6);
    return Math.min(dpr, 2.0);
  }

  setQualityLevel(level: QualityMode, scene?: Scene, camera?: Camera) {
    this.qualityLevel = level;
    const pixelRatio = this._calculatePixelRatio(level);
    this.renderer.setPixelRatio(pixelRatio);
    this.#basePixelRatio = pixelRatio;

    const targetFps = this.qualityLevel === QualityMode.Low ? 30 : 60;
    this.#targetMs = 1000 / targetFps;
    this.#emaMs = this.#targetMs;

    this.renderer.shadowMap.enabled = this.qualityLevel > QualityMode.Low;
    this.renderer.shadowMap.needsUpdate = true;

    if (scene && camera) {
      this.setupPostProcessing(scene, camera);
    }
  }

  // In your FuseRenderer class, add a setup method:
  setupPostProcessing(scene: Scene, camera: Camera) {
    if (!(this.renderer instanceof WebGPURenderer)) {
      console.warn('Post-processing pipeline requires WebGPURenderer');
      this.pipeline = undefined;
      return;
    }
    // Low tier: direct render, no post pipeline overhead
    if (this.qualityLevel === QualityMode.Low) {
      this.pipeline = undefined;
      return;
    }

    try {
      this.pipeline = new RenderPipeline(this.renderer);

      // WebGPU spec (and Apple Metal) strictly requires sampleCount to be 1 or 4 (never 2!)
      const scenePass = pass(scene, camera, { samples: 4 });

      // Get the color output texture node
      const scenePassColor = scenePass.getTextureNode('output');
      if (this.qualityLevel === QualityMode.Medium) {
        this.pipeline.outputNode = scenePassColor;
        return;
      }

      // High and Epic bloom effects - tuned for razor-sharp HDR highlights without foggy hazing
      const isEpic = this.qualityLevel >= QualityMode.VeryHigh;
      const strength = isEpic ? 0.14 : 0.08;
      const radius = isEpic ? 0.08 : 0.05;
      const threshold = isEpic ? 0.82 : 0.88;
      const bloomPass = bloom(scenePassColor, strength, radius, threshold);

      // Combine: original scene + crisp highlight bloom
      this.pipeline.outputNode = scenePassColor.add(bloomPass);
    } catch (err) {
      console.warn('[FuseRenderer] Failed to setup post-processing pipeline, using direct render:', err);
      this.pipeline = undefined;
    }
  }


  /**
   * DEBUG: compile the scene one mesh at a time, logging before/after each,
   * so the material that hangs the driver's shader compiler identifies itself.
   * The last "[probe] compiling ..." without a matching "[probe] ok" is the culprit.
   */
  async compileProbe(scene: Scene, camera: Camera) {
    if (!(this.renderer instanceof WebGPURenderer)) return;

    const meshes: any[] = [];
    scene.traverse((o: any) => { if (o.isMesh) meshes.push(o); });

    // Hide everything, remember prior visibility
    const prevVisible = meshes.map(o => o.visible);
    for (const o of meshes) o.visible = false;

    for (let i = 0; i < meshes.length; i++) {
      const o = meshes[i];
      const matType = Array.isArray(o.material)
        ? o.material.map((m: any) => m.type).join(',')
        : o.material?.type;
      o.visible = true;
      console.log(`[probe] compiling ${i + 1}/${meshes.length}: name="${o.name || '(unnamed)'}" obj=${o.constructor.name} mat=${matType}`);
      const t0 = performance.now();
      await this.renderer.compileAsync(scene, camera);
      console.log(`[probe] ok ${i + 1} (${(performance.now() - t0).toFixed(0)}ms)`);
      // Leave visible: compileAsync skips already-compiled pipelines on later passes
    }

    // Restore original visibility
    meshes.forEach((o, i) => (o.visible = prevVisible[i]));
  }  

  #adjustResolution() {
    if (!this.#adaptiveActive) return;
    const now = performance.now();
    if (this.#lastFrameT) {
      const dt = Math.min(now - this.#lastFrameT, 100); // ignore tab-switch spikes
      this.#emaMs = this.#emaMs * 0.95 + dt * 0.05;
    }
    this.#lastFrameT = now;
    if (this.adaptiveHold) {
      // EMA stays warm; on release, wait the normal cooldown before acting
      this.#lastAdjustT = now;
      return;
    }

    const prev = this.#scale;
    if (this.#emaMs > this.#targetMs * 1.15) {
      // Struggling: step down (at most 1x/sec), and pause recovery probes
      if (now - this.#lastAdjustT < 1000) return;
      this.#lastAdjustT = now;
      this.#scale = Math.max(this.#minScale, this.#scale - 0.1);
      this.#recoverAfter = now + 4000;
    } else if (this.#emaMs < this.#targetMs * 1.05 && this.#scale < 1 && now > this.#recoverAfter) {
      // Meeting target (rAF can't beat it — vsync floor): probe upward,
      // then wait a few seconds; if the probe hurts, the branch above reverts.
      this.#lastAdjustT = now;
      this.#scale = Math.min(1, this.#scale + 0.05);
      this.#recoverAfter = now + 3000;
    }

    if (this.#scale !== prev) {
      const pr = this.#basePixelRatio * this.#scale;
      console.warn(`Adjusting pixel ratio to ${pr}`);
      this.renderer.setPixelRatio(pr);
    }
  }
  startAdaptiveResolution() {
    this.#emaMs = this.#targetMs;   // clean history
    this.#lastFrameT = 0;           // don't count the gap since load began
    this.#adaptiveActive = true;
  }
}